def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])

    counts = Counter()
    for r in range(H):
        for c in range(W):
            counts[grid[r][c]] += 1
    bg_color = max(counts, key=counts.get)

    non_bg_colors = [c for c in counts if c != bg_color]
    core_color = None
    r_core, c_core = None, None

    # Find 2x2 block of a color
    for c in non_bg_colors:
        for r in range(H - 1):
            for col in range(W - 1):
                if grid[r][col] == c and grid[r+1][col] == c and \
                   grid[r][col+1] == c and grid[r+1][col+1] == c:
                    core_color = c
                    r_core, c_core = r, col
                    break
            if core_color: break
        if core_color: break

    if core_color is None:
        return grid

    pattern_color = None
    for c in non_bg_colors:
        if c != core_color:
            pattern_color = c
            break

    pattern_pixels = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == pattern_color:
                pattern_pixels.append((r, c))

    res_grid = [[bg_color for _ in range(W)] for _ in range(H)]

    # Place Core
    for r in range(r_core, r_core + 2):
        for c in range(c_core, c_core + 2):
            res_grid[r][c] = core_color

    # Center of Core (as float for calculation)
    center_r = r_core + 0.5
    center_c = c_core + 0.5

    for r, c in pattern_pixels:
        # Original position
        res_grid[r][c] = pattern_color

        # Horizontal reflection (across vertical center axis)
        c_rel = int(round(2 * center_c - c))
        if 0 <= c_rel < W:
            res_grid[r][c_rel] = pattern_color

        # Vertical reflection (across horizontal center axis)
        r_rel = int(round(2 * center_r - r))
        if 0 <= r_rel < H:
            res_grid[r_rel][c] = pattern_color

        # 180 rotation around center
        r_r, c_r = r_rel, c_rel
        if 0 <= r_r < H and 0 <= c_r < W:
            res_grid[r_r][c_r] = pattern_color

    return res_grid
